"use client"

import * as React from "react"
import {
  COLOR_THEME_ATTRIBUTE,
  COLOR_THEME_STORAGE_KEY,
  DEFAULT_COLOR_THEME,
  colorThemes,
  isColorThemeId,
  type ColorTheme,
  type ColorThemeId,
} from "@/lib/themes"

/* ------------------------------------------------------------------ */
/*  Context                                                            */
/* ------------------------------------------------------------------ */

export interface ColorThemeContextValue {
  /** The id of the active color theme. */
  colorTheme: ColorThemeId
  /** The full registry entry for the active color theme. */
  theme: ColorTheme
  /** Every registered color theme, in display order. */
  themes: readonly ColorTheme[]
  /** Activate a color theme. Persists and syncs across tabs. */
  setColorTheme: (id: ColorThemeId) => void
  /** Back to the default color theme. */
  resetColorTheme: () => void
}

const ColorThemeContext = React.createContext<ColorThemeContextValue | null>(null)

/* ------------------------------------------------------------------ */
/*  Tiny external store backed by localStorage                        */
/* ------------------------------------------------------------------ */

const CHANGE_EVENT = "color-theme-change"

function subscribe(onChange: () => void) {
  window.addEventListener("storage", onChange)
  window.addEventListener(CHANGE_EVENT, onChange)
  return () => {
    window.removeEventListener("storage", onChange)
    window.removeEventListener(CHANGE_EVENT, onChange)
  }
}

function readStored(storageKey: string): string | null {
  try {
    return window.localStorage.getItem(storageKey)
  } catch {
    return null
  }
}

function writeStored(storageKey: string, value: string) {
  try {
    window.localStorage.setItem(storageKey, value)
  } catch {
    /* storage can be unavailable (private mode, blocked); the attribute still applies */
  }
}

/**
 * Script that runs before React hydrates so the first paint already has the
 * right `data-theme`. Same technique next-themes uses for light/dark.
 */
function inlineScript(storageKey: string, attribute: string, fallback: string, ids: readonly string[]) {
  return `(function(){try{var k=${JSON.stringify(storageKey)},a=${JSON.stringify(attribute)},d=${JSON.stringify(fallback)},ok=${JSON.stringify(ids)};var t=localStorage.getItem(k);if(!t||ok.indexOf(t)===-1)t=d;document.documentElement.setAttribute(a,t)}catch(e){}})()`
}

/* ------------------------------------------------------------------ */
/*  Provider                                                           */
/* ------------------------------------------------------------------ */

export interface ColorThemeProviderProps {
  children: React.ReactNode
  /** Theme used when nothing is stored yet. Defaults to `"default"`. */
  defaultTheme?: ColorThemeId
  /** localStorage key. Defaults to `"color-theme"`. */
  storageKey?: string
  /** CSP nonce forwarded to the inline script. */
  nonce?: string
}

export function ColorThemeProvider({
  children,
  defaultTheme = DEFAULT_COLOR_THEME,
  storageKey = COLOR_THEME_STORAGE_KEY,
  nonce,
}: ColorThemeProviderProps) {
  const stored = React.useSyncExternalStore(
    subscribe,
    () => readStored(storageKey),
    () => null
  )

  const colorTheme: ColorThemeId = isColorThemeId(stored) ? stored : defaultTheme

  const setColorTheme = React.useCallback(
    (id: ColorThemeId) => {
      if (!isColorThemeId(id)) return
      writeStored(storageKey, id)
      document.documentElement.setAttribute(COLOR_THEME_ATTRIBUTE, id)
      window.dispatchEvent(new Event(CHANGE_EVENT))
    },
    [storageKey]
  )

  const resetColorTheme = React.useCallback(() => setColorTheme(defaultTheme), [setColorTheme, defaultTheme])

  // Keep <html data-theme> aligned with the store (covers cross-tab updates).
  React.useEffect(() => {
    document.documentElement.setAttribute(COLOR_THEME_ATTRIBUTE, colorTheme)
  }, [colorTheme])

  const value = React.useMemo<ColorThemeContextValue>(
    () => ({
      colorTheme,
      theme: colorThemes.find((t) => t.id === colorTheme) ?? colorThemes[0],
      themes: colorThemes,
      setColorTheme,
      resetColorTheme,
    }),
    [colorTheme, setColorTheme, resetColorTheme]
  )

  const script = React.useMemo(
    () => inlineScript(storageKey, COLOR_THEME_ATTRIBUTE, defaultTheme, colorThemes.map((t) => t.id)),
    [storageKey, defaultTheme]
  )

  return (
    <ColorThemeContext.Provider value={value}>
      <script nonce={nonce} suppressHydrationWarning dangerouslySetInnerHTML={{ __html: script }} />
      {children}
    </ColorThemeContext.Provider>
  )
}

/* ------------------------------------------------------------------ */
/*  Hook                                                               */
/* ------------------------------------------------------------------ */

export function useColorTheme(): ColorThemeContextValue {
  const ctx = React.useContext(ColorThemeContext)
  if (!ctx) {
    throw new Error("useColorTheme must be used within <ColorThemeProvider>")
  }
  return ctx
}

"use client"

import * as React from "react"
import { ThemeProvider as NextThemesProvider, type ThemeProviderProps as NextThemesProviderProps } from "next-themes"
import { ColorThemeProvider, type ColorThemeProviderProps } from "./color-theme-provider"

export interface ThemeProviderProps extends Omit<NextThemesProviderProps, "children"> {
  children: React.ReactNode
  /** Props forwarded to the color theme layer. */
  color?: Omit<ColorThemeProviderProps, "children">
}

/**
 * Composes next-themes (light / dark / system via the `class` attribute)
 * with the color theme layer (`data-theme` attribute).
 *
 * Mode and color are independent: switching to dark never changes the
 * chosen color, and picking a color never changes the mode.
 */
export function ThemeProvider({ children, color, ...props }: ThemeProviderProps) {
  return (
    <NextThemesProvider
      attribute="class"
      defaultTheme="system"
      enableSystem
      disableTransitionOnChange
      {...props}
    >
      <ColorThemeProvider {...color}>{children}</ColorThemeProvider>
    </NextThemesProvider>
  )
}

export { ColorThemeProvider, useColorTheme } from "./color-theme-provider"

"use client"

import * as React from "react"
import * as PopoverPrimitive from "@radix-ui/react-popover"
import { PaletteIcon, RotateCcwIcon } from "lucide-react"
import { useColorTheme } from "./color-theme-provider"
import { ModeSegmentedControl } from "./mode-toggle"
import { ThemeSwatch } from "./theme-swatch"
import { Button, buttonVariants } from "@/components/ui/button"
import { cn } from "@/lib/utils"

/**
 * Grid of every registered color theme. Reusable on its own
 * (the hero section uses it too).
 */
export function ColorThemeGrid({
  size = "md",
  className,
}: {
  size?: "sm" | "md" | "lg"
  className?: string
}) {
  const { themes, colorTheme, setColorTheme } = useColorTheme()

  return (
    <div role="radiogroup" aria-label="Color theme" className={cn("flex flex-wrap gap-2", className)}>
      {themes.map((t) => (
        <ThemeSwatch
          key={t.id}
          themeId={t.id}
          label={t.label}
          size={size}
          selected={t.id === colorTheme}
          onSelect={setColorTheme}
        />
      ))}
    </div>
  )
}

/**
 * The theme switcher: a popover with an appearance control (light / dark /
 * system) and the color theme grid. Drop it anywhere inside <ThemeProvider>.
 *
 * The popover is built on the Radix primitive directly so this component
 * works regardless of which shadcn/ui style (Radix or Base UI) the host app
 * uses.
 */
export function ThemeSwitcher({ className }: { className?: string }) {
  const { theme, colorTheme, resetColorTheme } = useColorTheme()

  return (
    <PopoverPrimitive.Root>
      {/* Styled with buttonVariants instead of asChild so the shadcn CLI can
          install this file unchanged into both Radix and Base UI projects. */}
      <PopoverPrimitive.Trigger
        aria-label="Open theme settings"
        className={cn(buttonVariants({ variant: "outline" }), "gap-2", className)}
      >
        <span aria-hidden className="size-3.5 rounded-full bg-primary ring-1 ring-foreground/10 ring-inset" />
        <span className="hidden sm:inline">{theme.label}</span>
        <PaletteIcon className="size-4 text-muted-foreground" />
      </PopoverPrimitive.Trigger>
      <PopoverPrimitive.Portal>
        <PopoverPrimitive.Content
          align="end"
          sideOffset={6}
          className={cn(
            "z-50 w-72 rounded-md border bg-popover p-0 text-popover-foreground shadow-md outline-hidden",
            "origin-(--radix-popover-content-transform-origin)",
            "data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95"
          )}
        >
          <section className="space-y-2 p-4">
            <h3 className="text-sm font-semibold">Appearance</h3>
            <ModeSegmentedControl />
          </section>
          <div role="separator" className="h-px w-full bg-border" />
          <section className="space-y-3 p-4">
            <div className="flex items-center justify-between">
              <h3 className="text-sm font-semibold">Color</h3>
              <Button
                variant="ghost"
                size="sm"
                className="h-7 gap-1 px-2 text-xs text-muted-foreground"
                onClick={resetColorTheme}
                disabled={colorTheme === "default"}
              >
                <RotateCcwIcon className="size-3" />
                Reset
              </Button>
            </div>
            <ColorThemeGrid size="lg" className="grid grid-cols-6 place-items-center gap-y-3" />
            <p className="text-xs text-muted-foreground">
              <span className="font-medium text-foreground">{theme.label}</span> · {theme.description}
            </p>
          </section>
        </PopoverPrimitive.Content>
      </PopoverPrimitive.Portal>
    </PopoverPrimitive.Root>
  )
}

"use client"

import * as React from "react"
import { CheckIcon } from "lucide-react"
import { cn } from "@/lib/utils"
import type { ColorThemeId } from "@/lib/themes"

export interface ThemeSwatchProps extends Omit<React.ComponentProps<"button">, "onSelect"> {
  themeId: ColorThemeId
  label: string
  selected?: boolean
  size?: "sm" | "md" | "lg"
  onSelect?: (id: ColorThemeId) => void
}

const sizes = {
  sm: "size-6",
  md: "size-8",
  lg: "size-10",
}

/**
 * A circular preview of a color theme's primary color.
 *
 * It sets `data-theme` on itself, so the CSS rules in globals.css resolve
 * `--primary` for that theme on this element, in the current light/dark
 * mode, with no hard-coded hex values anywhere.
 */
export function ThemeSwatch({ themeId, label, selected = false, size = "md", onSelect, className, ...props }: ThemeSwatchProps) {
  return (
    <button
      type="button"
      role="radio"
      aria-checked={selected}
      aria-label={label}
      title={label}
      data-theme={themeId}
      data-selected={selected ? "" : undefined}
      onClick={() => onSelect?.(themeId)}
      className={cn(
        "group relative inline-flex shrink-0 items-center justify-center rounded-full bg-primary text-primary-foreground",
        "ring-offset-background transition-transform duration-150 ease-out",
        "hover:scale-110 focus-visible:scale-110 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
        "data-selected:ring-2 data-selected:ring-primary data-selected:ring-offset-2",
        sizes[size],
        className
      )}
      {...props}
    >
      <CheckIcon
        aria-hidden
        className={cn("size-1/2 transition-opacity", selected ? "opacity-100" : "opacity-0 group-hover:opacity-40")}
        strokeWidth={3}
      />
    </button>
  )
}

"use client"

import * as React from "react"
import { useTheme } from "next-themes"
import { MonitorIcon, MoonIcon, SunIcon } from "lucide-react"
import { modes, type Mode } from "@/lib/themes"
import { cn } from "@/lib/utils"
import { useMounted } from "@/hooks/use-mounted"
import { Button } from "@/components/ui/button"

const icons: Record<Mode, React.ComponentType<{ className?: string }>> = {
  light: SunIcon,
  dark: MoonIcon,
  system: MonitorIcon,
}

/** Segmented control: Light / Dark / System. */
export function ModeSegmentedControl({ className }: { className?: string }) {
  const { theme, setTheme } = useTheme()
  const mounted = useMounted()
  const current = (mounted ? theme : undefined) as Mode | undefined

  return (
    <div role="radiogroup" aria-label="Appearance" className={cn("grid grid-cols-3 gap-1 rounded-lg bg-muted p-1", className)}>
      {modes.map((m) => {
        const Icon = icons[m.id]
        const active = current === m.id
        return (
          <button
            key={m.id}
            type="button"
            role="radio"
            aria-checked={active}
            onClick={() => setTheme(m.id)}
            className={cn(
              "flex items-center justify-center gap-1.5 rounded-md px-2 py-1.5 text-xs font-medium transition-colors",
              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
              active ? "bg-background text-foreground shadow-sm" : "text-muted-foreground hover:text-foreground"
            )}
          >
            <Icon className="size-3.5" />
            {m.label}
          </button>
        )
      })}
    </div>
  )
}

/** Compact sun / moon button that flips between light and dark. */
export function ModeToggle({ className }: { className?: string }) {
  const { resolvedTheme, setTheme } = useTheme()
  const mounted = useMounted()
  const isDark = mounted && resolvedTheme === "dark"

  return (
    <Button
      variant="outline"
      size="icon"
      aria-label={isDark ? "Switch to light mode" : "Switch to dark mode"}
      onClick={() => setTheme(isDark ? "light" : "dark")}
      className={className}
    >
      <SunIcon className="size-4 scale-100 rotate-0 transition-all dark:scale-0 dark:-rotate-90" />
      <MoonIcon className="absolute size-4 scale-0 rotate-90 transition-all dark:scale-100 dark:rotate-0" />
    </Button>
  )
}

import { useSyncExternalStore } from "react"

const subscribe = () => () => {}

/**
 * `false` during SSR and hydration, `true` once the component is on the client.
 * Uses `useSyncExternalStore` so there is no extra render or state update.
 */
export function useMounted() {
  return useSyncExternalStore(
    subscribe,
    () => true,
    () => false
  )
}
